#include <string>
#include <vector>
#include <unordered_set>
#include <unordered_map>
#include <algorithm>

class Solution {
public:
    std::string sortVowelsByFrequency(std::string s) {
        std::unordered_set<char> vowelsSet = {'a', 'e', 'i', 'o', 'u'};
        std::vector<char> vowels;
        for (char c : s) {
            if (vowelsSet.count(c)) vowels.push_back(c);
        }
        std::unordered_map<char, int> freq;
        std::unordered_map<char, int> firstSeen;
        for (int i = 0; i < (int)vowels.size(); ++i) {
            char c = vowels[i];
            if (!freq.count(c)) {
                freq[c] = 0;
                firstSeen[c] = i;
            }
            freq[c]++;
        }
        std::vector<char> uniqueVowels;
        for (auto& [c, f] : freq) uniqueVowels.push_back(c);
        std::sort(uniqueVowels.begin(), uniqueVowels.end(), [&](char a, char b) {
            if (freq[a] != freq[b]) return freq[a] > freq[b];
            return firstSeen[a] < firstSeen[b];
        });
        std::vector<char> sortedVowels;
        for (char c : uniqueVowels) {
            sortedVowels.insert(sortedVowels.end(), freq[c], c);
        }
        int idx = 0;
        for (int i = 0; i < (int)s.length(); ++i) {
            if (vowelsSet.count(s[i])) {
                s[i] = sortedVowels[idx++];
            }
        }
        return s;
    }
};

import java.util.*;

class Solution {
    public String sortVowelsByFrequency(String s) {
        Set<Character> vowelsSet = Set.of('a', 'e', 'i', 'o', 'u');
        List<Character> vowels = new ArrayList<>();
        for (char c : s.toCharArray()) {
            if (vowelsSet.contains(c)) vowels.add(c);
        }
        Map<Character, Integer> freq = new HashMap<>();
        Map<Character, Integer> firstSeen = new HashMap<>();
        for (int i = 0; i < vowels.size(); i++) {
            char c = vowels.get(i);
            freq.put(c, freq.getOrDefault(c, 0) + 1);
            firstSeen.putIfAbsent(c, i);
        }
        List<Character> uniqueVowels = new ArrayList<>(freq.keySet());
        uniqueVowels.sort((a, b) -> {
            if (!freq.get(a).equals(freq.get(b))) return freq.get(b) - freq.get(a);
            return firstSeen.get(a) - firstSeen.get(b);
        });
        List<Character> sortedVowels = new ArrayList<>();
        for (char c : uniqueVowels) {
            int count = freq.get(c);
            for (int i = 0; i < count; i++) sortedVowels.add(c);
        }
        char[] arr = s.toCharArray();
        int idx = 0;
        for (int i = 0; i < arr.length; i++) {
            if (vowelsSet.contains(arr[i])) {
                arr[i] = sortedVowels.get(idx++);
            }
        }
        return new String(arr);
    }
}

function sortVowelsByFrequency(s) {
    const vowelsSet = new Set(['a', 'e', 'i', 'o', 'u']);
    const vowels = [];
    for (const c of s) {
        if (vowelsSet.has(c)) vowels.push(c);
    }
    const freq = new Map();
    const firstSeen = new Map();
    for (let i = 0; i < vowels.length; i++) {
        const c = vowels[i];
        freq.set(c, (freq.get(c) || 0) + 1);
        if (!firstSeen.has(c)) firstSeen.set(c, i);
    }
    const uniqueVowels = Array.from(freq.keys());
    uniqueVowels.sort((a, b) => {
        if (freq.get(a) !== freq.get(b)) return freq.get(b) - freq.get(a);
        return firstSeen.get(a) - firstSeen.get(b);
    });
    const sortedVowels = [];
    for (const c of uniqueVowels) {
        const count = freq.get(c);
        for (let i = 0; i < count; i++) sortedVowels.push(c);
    }
    const res = s.split('');
    let idx = 0;
    for (let i = 0; i < res.length; i++) {
        if (vowelsSet.has(res[i])) {
            res[i] = sortedVowels[idx++];
        }
    }
    return res.join('');
}
